'use client';

import {useMemo,useRef,type AnchorHTMLAttributes,type ButtonHTMLAttributes,type Ref} from 'react';
import {mergeRefs} from 'react-aria';
import {useMotionTokens} from '@/hooks/use-motion-tokens';
import { Button as AriaButton, ProgressBar as AriaProgressBar, type ButtonProps as AriaButtonProps } from 'react-aria-components';
import { AnimatePresence, motion } from 'motion/react';
import { useMediaQuery } from '@/hooks/use-media-query';
import { Spinner } from '@/components/base/spinner/spinner';
import type { IconComponent } from '@/components/foundations/icon-types';
import { cx } from '@/utils/cx';

export type IconButtonSize = 'medium' | 'small' | 'xs';

export type IconButtonProps = Omit<ButtonHTMLAttributes<HTMLButtonElement>, 'children' | 'aria-label' | 'onFocus' | 'onBlur' | 'onKeyDown' | 'onKeyUp' | 'onClick'> & Pick<AriaButtonProps, 'onFocus' | 'onBlur' | 'onKeyDown' | 'onKeyUp' | 'onClick' | 'isPending' | 'preventFocusOnPress'> & {
  icon: IconComponent;
  /** Animate a glyph change without moving or remounting its button. */
  iconKey?: string | number;
  pendingLabel?: string;
  size?: IconButtonSize;
  variant?: 'secondary' | 'ghost';
  badge?: number;
  ref?: Ref<HTMLButtonElement>;
  'aria-label': string;
};

export type IconLinkButtonProps = Omit<AnchorHTMLAttributes<HTMLAnchorElement>, 'children' | 'aria-label'> & {
  icon: IconComponent;
  size?: IconButtonSize;
  'aria-label': string;
};

export function IconButton({ icon: Icon, iconKey, pendingLabel = 'Working', isPending, size = 'medium', variant = 'secondary', badge, className, type = 'button', disabled, value, ref, ...props }: IconButtonProps) {
  const reducedMotion = useMediaQuery('(prefers-reduced-motion: reduce)');
  const root=useRef<HTMLButtonElement>(null),composed=useMemo(()=>mergeRefs(root,ref),[ref]),tokens=useMotionTokens(root);
  return <AriaButton {...props} ref={composed} type={type} value={value === undefined ? undefined : String(value)} isDisabled={disabled} isPending={isPending} data-size={size} data-variant={variant} className={cx('ui-icon-button', className)}>{iconKey === undefined ? <Icon className="ui-icon-button__icon" aria-hidden /> : <span className="ui-icon-button__glyph" aria-hidden><AnimatePresence initial={false}><motion.span key={iconKey} data-icon-key={iconKey} initial={reducedMotion ? false : { opacity: 0, scale: .65, y: 2 }} animate={{ opacity: 1, scale: 1, y: 0 }} exit={reducedMotion ? { opacity: 0 } : { opacity: 0, scale: .65, y: -2 }} transition={{ duration: reducedMotion ? 0 : tokens.fast, ease: tokens.ease }}><Icon className="ui-icon-button__icon"/></motion.span></AnimatePresence></span>}<span className="ui-icon-button__pending" aria-hidden><Spinner size={size === 'medium' ? 'md' : 'sm'}/></span>{isPending && <AriaProgressBar aria-label={pendingLabel} isIndeterminate className="sr-only"/>}{badge !== undefined && badge > 0 && <span className="ui-icon-button__badge" aria-hidden>{badge > 99 ? '99+' : badge}</span>}</AriaButton>;
}

export function IconLinkButton({ icon: Icon, size = 'medium', className, ...props }: IconLinkButtonProps) {
  return <a data-size={size} className={cx('ui-icon-button', className)} {...props}><Icon className="ui-icon-button__icon" aria-hidden /></a>;
}

import type { HTMLAttributes, ReactNode } from 'react';
import { cx } from '@/utils/cx';

export type CollapsibleProps = Omit<HTMLAttributes<HTMLDivElement>, 'children'> & { isOpen: boolean; children: ReactNode };

/** Keep descendants mounted while hiding their focus targets and animating flow. */
export function Collapsible({ isOpen, children, className, ...props }: CollapsibleProps) {
  return <div {...props} className={cx('ui-collapsible', className)} data-open={isOpen || undefined} aria-hidden={!isOpen} inert={!isOpen}>
    <div className="ui-collapsible__inner"><div className="ui-collapsible__content">{children}</div></div>
  </div>;
}

'use client';

import { useId, useMemo } from 'react';
import { Label, Meter as AriaMeter, useLocale, type MeterProps as AriaMeterProps } from 'react-aria-components';
import { cx } from '@/utils/cx';

export type MeterSegment = { id: string; label: string; value: number; color?: string };
export type MeterProps = Omit<AriaMeterProps, 'children' | 'className'> & {
  label: string;
  hideLabel?: boolean;
  showValue?: boolean;
  size?: 'small' | 'medium' | 'large';
  tone?: 'accent' | 'success' | 'warning' | 'danger';
  /** Quantities within the displayed amount; remaining usage keeps the base tone. */
  segments?: MeterSegment[];
  className?: string;
};

/** A bounded quantity, with optional parts that share the same value scale. */
export function Meter({ label, hideLabel = false, showValue = true, size = 'medium', tone = 'accent', segments, className, value = 0, minValue = 0, maxValue = 100, 'aria-describedby': describedBy, ...props }: MeterProps) {
  const detailsId = useId();
  const { locale } = useLocale();
  const partFormatter = useMemo(() => new Intl.NumberFormat(locale, { maximumFractionDigits: 2 }), [locale]);
  const minimum = Number.isFinite(minValue) ? minValue : 0;
  const maximum = Number.isFinite(maxValue) && maxValue > minimum ? maxValue : minimum + 1;
  const current = Math.min(maximum, Math.max(minimum, Number.isFinite(value) ? value : minimum));
  const range = maximum - minimum;
  let remaining = current - minimum;
  const parts = segments?.map(segment => {
    const amount = Math.min(remaining, Math.max(0, Number.isFinite(segment.value) ? segment.value : 0));
    remaining -= amount;
    return { ...segment, amount, width: amount / range * 100 };
  });
  return <AriaMeter {...props} value={current} minValue={minimum} maxValue={maximum} aria-describedby={[describedBy, parts?.length ? detailsId : undefined].filter(Boolean).join(' ') || undefined} className={cx('ui-meter', className)} data-size={size} data-tone={tone}>
    {({ percentage, valueText }) => <>
      <div className="ui-meter__heading"><Label className={cx('ui-meter__label', hideLabel && 'sr-only')}>{label}</Label>{showValue && <span className="ui-meter__value" aria-hidden>{valueText}</span>}</div>
      <div className="ui-meter__track" aria-hidden>
        {parts?.length ? <>{parts.map(part => <span key={part.id} className="ui-meter__segment" style={{ width: `${part.width}%`, background: part.color }}/>)}<span className="ui-meter__segment ui-meter__remainder" style={{ width: `${remaining / range * 100}%` }}/></> : <span className="ui-meter__fill" style={{ width: `${percentage}%` }}/>}
      </div>
      {!!parts?.length && <span id={detailsId} className="sr-only">{parts.map(part => `${part.label}: ${partFormatter.format(part.amount)}`).join('; ')}{remaining > 0 ? `; Other: ${partFormatter.format(remaining)}` : ''}</span>}
    </>}
  </AriaMeter>;
}

import type { CSSProperties } from 'react';
import { cx } from '@/utils/cx';

export type SpinnerProps = {
  size?: 'xs' | 'sm' | 'md' | 'lg';
  label?: string;
  className?: string;
  style?: CSSProperties;
};

/** Omit the label when a containing busy control already names the operation. */
export function Spinner({ size = 'md', label, className, style }: SpinnerProps) {
  return <span className={cx('ui-spinner', className)} data-size={size} role={label ? 'status' : undefined} aria-label={label} aria-hidden={!label || undefined} style={style}>
    <svg viewBox="0 0 24 24" fill="none" aria-hidden><circle cx="12" cy="12" r="9" stroke="currentColor" strokeWidth="2" opacity=".18"/><path d="M12 3a9 9 0 0 1 9 9" stroke="currentColor" strokeWidth="2" strokeLinecap="round"/></svg>
  </span>;
}

'use client';

import { useId, useState } from 'react';
import { RiArrowDownSLine, RiArrowRightLine } from '@remixicon/react';
import { Collapsible } from '@/components/base/collapsible/collapsible';
import { IconButton } from '@/components/base/buttons/icon-button';
import { Meter, type MeterProps } from '@/components/base/meter/meter';
import { cx } from '@/utils/cx';

type UsageTone = NonNullable<MeterProps['tone']>;
export type AgentLimit = { id: string; label: string; used: number; maximum: number; resetLabel?: string; members?: { name: string; used: number }[]; tone?: UsageTone };
export type AgentLimitsCardProps = {
  contextUsed: number;
  contextMaximum: number;
  buckets?: { label: string; amount: number; color: string }[];
  limits: AgentLimit[];
  contextLabel?: string;
  limitsLabel?: string;
  density?: 'normal' | 'compact';
  variant?: 'soft' | 'bordered';
  defaultExpanded?: boolean;
  isExpanded?: boolean;
  onExpandedChange?: (expanded: boolean) => void;
  defaultOpenLimit?: string | null;
  openLimit?: string | null;
  onOpenLimitChange?: (id: string | null) => void;
  formatValue?: (value: number) => string;
  onPlanClick?: () => void;
  className?: string;
};
const compactFormatter = new Intl.NumberFormat('en-US', { notation: 'compact', maximumFractionDigits: 1 });
const formatCompact = (value: number) => compactFormatter.format(value);
const finiteAmount = (value: number) => Number.isFinite(value) ? Math.max(0, value) : 0;
const percentage = (used: number, maximum: number) => maximum > 0 && Number.isFinite(maximum) ? Math.min(100, finiteAmount(used) / maximum * 100) : 0;
const toneFor = (value: number): UsageTone => value >= 95 ? 'danger' : value >= 80 ? 'warning' : 'accent';

export function AgentLimitsCard({ contextUsed, contextMaximum, buckets = [], limits, contextLabel = 'Context window', limitsLabel = 'Plan usage limits', density = 'normal', variant = 'soft', defaultExpanded = false, isExpanded, onExpandedChange, defaultOpenLimit = null, openLimit, onOpenLimitChange, formatValue = formatCompact, onPlanClick, className }: AgentLimitsCardProps) {
  const [internalExpanded, setInternalExpanded] = useState(defaultExpanded);
  const [internalLimit, setInternalLimit] = useState<string | null>(defaultOpenLimit);
  const expanded = isExpanded ?? internalExpanded;
  const activeLimit = openLimit === undefined ? internalLimit : openLimit;
  const id = useId(), detailsId = `${id}-context`;
  const used = finiteAmount(contextUsed), maximum = finiteAmount(contextMaximum);
  const contextPercent = percentage(used, maximum);
  function toggleExpanded() {
    if (isExpanded === undefined) setInternalExpanded(!expanded);
    onExpandedChange?.(!expanded);
  }
  function toggleLimit(limit: string) {
    const next = activeLimit === limit ? null : limit;
    if (openLimit === undefined) setInternalLimit(next);
    onOpenLimitChange?.(next);
  }
  return <div className={cx('ui-agent-limits', className)} data-density={density} data-variant={variant}>
    <button type="button" className="ui-agent-limits__summary" aria-expanded={expanded} aria-controls={detailsId} onClick={toggleExpanded}>
      <span>{contextLabel}</span><strong>{formatValue(used)} / {maximum > 0 ? formatValue(maximum) : '—'}{maximum > 0 && ` (${Math.round(contextPercent)}%)`}</strong><RiArrowDownSLine size={16} aria-hidden/>
    </button>
    <Meter label={`${contextLabel} usage`} hideLabel showValue={false} value={Math.min(used, maximum)} maxValue={maximum || 1} valueLabel={maximum > 0 ? `${formatValue(used)} of ${formatValue(maximum)} used` : 'Limit not configured'} tone={toneFor(contextPercent)} className="ui-agent-limits__segments" segments={buckets.map((bucket, index) => ({ id: `${index}:${bucket.label}`, label: bucket.label, value: bucket.amount, color: bucket.color }))}/>
    {!!limits.length && <div className="ui-agent-limits__body"><div className="ui-agent-limits__heading"><span>{limitsLabel}</span>{onPlanClick && <IconButton icon={RiArrowRightLine} size="xs" variant="ghost" aria-label="View plan" onClick={onPlanClick}/>}</div>
      {limits.map((limit, index) => {
        const limitMaximum = finiteAmount(limit.maximum), percent = percentage(limit.used, limitMaximum), hasMembers = Boolean(limit.members?.length), detailId = `${id}-limit-${index}`;
        const heading = <><strong>{limit.label}</strong>{limit.resetLabel && <span>{limit.resetLabel}</span>}<b>{limitMaximum > 0 ? `${Math.round(percent)}%` : '—'}</b>{hasMembers && <RiArrowDownSLine size={14} aria-hidden/>}</>;
        return <div className="ui-agent-limits__limit" key={limit.id}>
          {hasMembers ? <button type="button" className="ui-agent-limits__limit-head" aria-expanded={activeLimit === limit.id} aria-controls={detailId} onClick={() => toggleLimit(limit.id)}>{heading}</button> : <div className="ui-agent-limits__limit-head">{heading}</div>}
          <Meter label={limit.label} value={finiteAmount(limit.used)} maxValue={limitMaximum || 1} valueLabel={limitMaximum > 0 ? `${formatValue(finiteAmount(limit.used))} of ${formatValue(limitMaximum)} used` : 'Limit not configured'} hideLabel showValue={false} size="small" tone={limit.tone ?? toneFor(percent)} className="ui-agent-limits__bar"/>
          {hasMembers && <Collapsible isOpen={activeLimit === limit.id} id={detailId}><div className="ui-agent-limits__members">{limit.members!.map((member, index) => <div className="ui-agent-limits__member" key={`${index}:${member.name}`}><span>{member.name}</span><span>{formatValue(finiteAmount(member.used))}</span></div>)}</div></Collapsible>}
        </div>;
      })}
    </div>}
    <Collapsible isOpen={expanded} id={detailsId}><div className="ui-agent-limits__details"><strong>Usage breakdown</strong>{buckets.map((bucket, index) => <div key={`${index}:${bucket.label}`}><span><i style={{ background: bucket.color }}/>{bucket.label}</span><b>{Math.round(percentage(bucket.amount, maximum))}%</b></div>)}<div><span>Available</span><b>{maximum > 0 ? formatValue(Math.max(0, maximum - used)) : '—'}</b></div></div></Collapsible>
  </div>;
}

'use client';

import { useCallback, useSyncExternalStore } from 'react';

export function useMediaQuery(query: string) {
  const subscribe = useCallback((notify: () => void) => {
    const media = window.matchMedia(query);
    media.addEventListener('change', notify);
    return () => media.removeEventListener('change', notify);
  }, [query]);
  const snapshot = useCallback(() => window.matchMedia(query).matches, [query]);
  return useSyncExternalStore(subscribe, snapshot, () => false);
}

// Keep these in sync with the navigation and inspector media queries in template CSS.
export const TEMPLATE_NAV_QUERY = '(max-width: 1023px)';
export const TEMPLATE_PANEL_QUERY = '(max-width: 1279px)';

'use client';

import {useLayoutEffect,useState,type RefObject} from 'react';

export type MotionTokens={fast:number;standard:number;settle:number;ease:[number,number,number,number]};
const defaults:MotionTokens={fast:.16,standard:.24,settle:.36,ease:[.2,.75,.25,1]};
function seconds(value:string,fallback:number){const match=value.trim().match(/^([\d.]+)(ms|s)$/);if(!match)return fallback;const amount=Number(match[1])/(match[2]==='ms'?1000:1);return Number.isFinite(amount)&&amount>=0?amount:fallback;}

/** Use the same scoped CSS tokens for JavaScript layout/glyph animation. */
export function useMotionTokens(scope?:RefObject<Element|null>){
  const [tokens,setTokens]=useState<MotionTokens>(defaults);
  useLayoutEffect(()=>{
    const element=scope?.current??document.documentElement;
    function read(){
      const style=getComputedStyle(element),curve=style.getPropertyValue('--motion-ease').match(/^\s*cubic-bezier\(([^)]+)\)/)?.[1].split(',').map(Number);
      const ease=curve?.length===4&&curve.every(Number.isFinite)?curve as MotionTokens['ease']:defaults.ease;
      const next={fast:seconds(style.getPropertyValue('--motion-fast'),defaults.fast),standard:seconds(style.getPropertyValue('--motion-standard'),defaults.standard),settle:seconds(style.getPropertyValue('--motion-settle'),defaults.settle),ease};
      setTokens(current=>current.fast===next.fast&&current.standard===next.standard&&current.settle===next.settle&&current.ease.every((value,index)=>value===next.ease[index])?current:next);
    }
    read();const observer=new MutationObserver(read);
    observer.observe(document.documentElement,{attributes:true,attributeFilter:['style','class','data-accent']});
    if(element!==document.documentElement)observer.observe(element,{attributes:true,attributeFilter:['style','class']});
    return()=>observer.disconnect();
  },[scope]);
  return tokens;
}

import { extendTailwindMerge } from 'tailwind-merge';

const typeFamilies = [
  'large-title', 'display-1', 'display-2', 'display-3', 'display-4',
  'title-1', 'title-2', 'title-3', 'headline', 'body', 'body-2',
  'caption-1', 'caption-2',
] as const;
const weights = ['regular', 'medium', 'semibold', 'bold'] as const;

// Custom text styles share Tailwind's text-* namespace with colors.
// Registering them keeps both classes when they appear together.
export const cx = extendTailwindMerge({
  extend: {
    classGroups: {
      'font-size': [{ text: typeFamilies.flatMap((family) => weights.map((weight) => `${family}-${weight}`)) }],
    },
  },
});
